CREATE COLUMN TABLE "TEST_AP"."OHPS" ("posID" INTEGER CS_INT NOT NULL , "name" NVARCHAR(20) NOT NULL , "descriptio" NCLOB MEMORY THRESHOLD 1000, "LocFields" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("posID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OHPS_NAME" ON "TEST_AP"."OHPS" ( "name" ASC )